    required this.priority,
    this.estimatedHours,
    this.estimatedCost,
    this.dueDate,
    required this.photoRequired,
    this.assignedTo,
    required this.materialsNeeded,
    this.zoneId,
    this.startDate,
    required this.version,
    required this.createdAt,
    required this.updatedAt,
    this.deletedAt,
  });
